async function runStage<T>(
	state: RunState,
	name: RunStageName,
	stage: () => Promise<T>,
): Promise<T | null> {
	const halted = state.halted;
	if (halted !== null) {
		const at = new Date().toISOString();
		state.rows.push(
			Object.freeze({
				name,
				status: 'not-run' as const,
				reason: notRunBecause(halted.stage, halted.status),
				startedAt: at,
				endedAt: at,
